with latest as (select * from inventory qualify row_number() over (partition by store_id order by last_restock desc, id) = 1) select case when quantity >= 245 then 'HIGH' else 'LOW' end as quantity_tier, stddev_samp(quantity) as quantity_stddev, approx_percentile(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles, min(quantity) as min_quantity from latest group by case when quantity >= 245 then 'HIGH' else 'LOW' end
